<template>
  <AppLoader v-if="isLoading && !exportInfo" subject="information to export" />
  <AppError v-else-if="error" :error="error" title="Failed to load export information" />
  <AppEmpty v-else-if="!exportInfo" subject="export information" />
  <div v-else class="grid grid-cols-4">
    <Card class="col-span-2 col-start-2">
      <CardHeader class="py-4">
        <h3 class="text-lg font-semibold">Export File</h3>
      </CardHeader>
      <CardContent class="flex flex-col gap-4">
        <ExportsProcessing
          v-if="status === 'new' || status === 'exporting'"
          :status="status"
          :refetch="refetchExport"
        />
        <State
          v-else-if="status === 'failed'"
          title="Failed to generate export"
          description="An error occurred while generating the export file."
          :icon="AlertOctagon"
          icon-class="stroke-destructive size-16 w-16"
        />
        <ExportsDone v-else-if="status === 'done'" :s3-url="exportInfo.s3_url" :export-type="exportInfo.type" />
      </CardContent>
    </Card>
  </div>
</template>

<script setup lang="ts">
import { AlertOctagon } from 'lucide-vue-next';
import { useExport } from '~/queries/exports';

definePageMeta({
  roles: ['admin', 'manager'],
  skipNavJourney: true,
});

const { exportInfo, error, isLoading, status, refetch } = useExport();

async function refetchExport() {
  await refetch().catch((error) => {
    console.error('Error refetching export:', error);
  });
}
</script>
