import { getExportJob } from '~/client';

export const useExport = defineQuery(() => {
  const route = useRoute('exports-id');
  const id = computed(() => route.params.id as string);

  const {
    data: exportInfo,
    error,
    isLoading,
    refetch,
  } = useQuery({
    key: () => ['exports', id.value],
    query: () => getExportJob({ composable: '$fetch', path: { export_job_id: id.value } }),
    staleTime: 0,
    enabled: () => Boolean(id.value) && route.name === 'exports-id',
  });

  return {
    exportInfo,
    error,
    isLoading,
    status: computed(() => exportInfo.value?.status),
    refetch,
    id,
  };
});
